if(!rh24_db_configured())finish(['ok'=>false,'error'=>'Shop-Datenbank ist noch nicht eingerichtet.'],503);
if($_SERVER['REQUEST_METHOD']!=='POST')finish(['ok'=>false,'error'=>'Methode nicht erlaubt'],405);
$data=json_decode(file_get_contents('php://input')?:'{}',true);if(!is_array($data))finish(['ok'=>false,'error'=>'Ungültige Anfrage'],400);if(!empty($data['website']))finish(['ok'=>false,'error'=>'Anfrage abgelehnt'],400);
$customer=is_array($data['customer']??null)?$data['customer']:[];$name=trim((string)($customer['name']??''));$email=strtolower(trim((string)($customer['email']??'')));$street=trim((string)($customer['street']??''));$zip=trim((string)($customer['zip']??''));$city=trim((string)($customer['city']??''));
if($name===''||!filter_var($email,FILTER_VALIDATE_EMAIL)||$street===''||$zip===''||$city==='')finish(['ok'=>false,'error'=>'Bitte vollständige Kundendaten angeben.'],422);
$items=$data['items']??[];if(!is_array($items)||count($items)<1||count($items)>50)finish(['ok'=>false,'error'=>'Warenkorb ist ungültig.'],422);
$catalog=rh24_catalog();$clean=[];$subtotal=0.0;$productWeightG=0;$shippingWeightG=0;
try{foreach($items as $row){if(!is_array($row))continue;$id=(string)($row['id']??'');$aliases=['mehlBuche'=>'mehl-buche','mehlErle'=>'mehl-erle','mehlBirke'=>'mehl-birke','mehlEiche'=>'mehl-eiche','mehlKirsche'=>'mehl-kirsche','lauForelle'=>'lauge-forelle-0','lauForelleChili'=>'lauge-forelle-2','lauForelleRed'=>'lauge-forelle-3','lauAal'=>'lauge-aal-0'];$id=$aliases[$id]??$id;$qty=max(1,min(99,(int)($row['qty']??1)));$meta=is_array($row['meta']??null)?$row['meta']:[];if(!isset($catalog[$id]))throw new InvalidArgumentException('Unbekannter Artikel im Warenkorb.');$price=rh24_resolve_price($id,$meta);if($price<=0)throw new InvalidArgumentException('Dieser Artikel ist noch nicht für den Verkauf freigegeben.');$line=round($price*$qty,2);$subtotal+=$line;$pw=max(0,(int)($catalog[$id]['product_weight_g']??0));$sw=max(0,(int)($catalog[$id]['shipping_weight_g']??0));$productWeightG+=$pw*$qty;$shippingWeightG+=$sw*$qty;$clean[]=['id'=>$id,'article_no'=>$catalog[$id]['article_no']??'','name'=>$catalog[$id]['name'],'unit'=>$catalog[$id]['unit'],'product_weight_g'=>$pw,'shipping_weight_g'=>$sw,'qty'=>$qty,'meta'=>$meta,'unit_price'=>$price,'line_total'=>$line];}}catch(Throwable $e){finish(['ok'=>false,'error'=>$e->getMessage()],422);}if(!$clean)finish(['ok'=>false,'error'=>'Warenkorb ist leer.'],422);
$cfg=rh24_config();$threshold=(float)($cfg['shipping_threshold']??39);$shipping=$subtotal>=$threshold?0.0:(float)($cfg['shipping_cost']??7);$gross=round($subtotal+$shipping,2);$vatRate=(float)($cfg['vat_rate']??19);$net=round($gross/(1+$vatRate/100),2);$vat=round($gross-$net,2);
$orderNo='RH24-'.date('Ymd').'-'.strtoupper(bin2hex(random_bytes(3)));$created=rh24_now();$cust=['name'=>$name,'email'=>$email,'phone'=>trim((string)($customer['phone']??'')),'street'=>$street,'zip'=>$zip,'city'=>$city,'company'=>trim((string)($customer['company']??''))];$totals=['subtotal'=>round($subtotal,2),'shipping'=>$shipping,'net'=>$net,'vat'=>$vat,'vat_rate'=>$vatRate,'gross'=>$gross,'product_weight_g'=>$productWeightG,'shipping_weight_g'=>$shippingWeightG];$history=[['at'=>date('c'),'type'=>'created','value'=>'Shopbestellung eingegangen'],['at'=>date('c'),'type'=>'payment','value'=>'pending']];
$db=rh24_db();
try{
  $db->beginTransaction();$customerId=rh24_customer_upsert($cust,$orderNo);
  $attr=rh24_resolve_sales_attribution($db,$customerId,'online','');
